// Custom Worker entry (architecture section 5, `worker/`). OpenNext generates the fetch handler;
// this file re-uses it and adds the scheduled handler and the Durable Object classes.
// `.open-next/worker.js` is generated by `opennextjs-cloudflare build`, so it does not exist before a build and @ts-expect-error would fail after one.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as handler } from "../.open-next/worker.js";

export default {
  fetch: handler.fetch,

  /**
   * S0.7: one Cron Trigger run (daily 23:05 UTC). Stage 0 only records that it ran. The real handler
   * (S7.1 and S10.2) does the event rollup, raw event purge and usage checks.
   */
  async scheduled(event, env, ctx) {
    const collector = env.COLLECTOR.get(env.COLLECTOR.idFromName("global")) as unknown as {
      recordCron(scheduledTime: number): Promise<void>;
    };
    ctx.waitUntil(collector.recordCron(event.scheduledTime));
  },
} satisfies ExportedHandler<CloudflareEnv>;

// Durable Object classes must be exported from the Worker entry.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore generated at build time (see above)
export { DOQueueHandler } from "../.open-next/worker.js";
export { Collector } from "./collector";
export { RateLimiter } from "./rate-limiter";
